"""Durable per-case evidence for serial full-suite shards."""
import json
import os
from pathlib import Path


def pytest_collection_finish(session):
    target = os.environ.get("LH003_COLLECTION")
    if target:
        Path(target).write_text(json.dumps([item.nodeid for item in session.items]))


# Open the diagnostic stream before tests install filesystem traps. Captured
# fd functions still pass through the interpreter audit hook; the only target
# is this process's explicitly configured /tmp journal.
_target = os.environ.get("LH003_TEST_JOURNAL")
_fd = os.open(_target, os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o600) if _target else None
_write, _sync, _close = os.write, os.fsync, os.close


def append(value):
    if _fd is not None:
        content = (json.dumps(value) + "\n").encode()
        while content:
            content = content[_write(_fd, content):]
        _sync(_fd)


def pytest_sessionfinish(session, exitstatus):
    if _fd is not None:
        _close(_fd)


def pytest_runtest_logstart(nodeid, location):
    append({"nodeid": nodeid, "phase": "start"})


def pytest_runtest_logreport(report):
    append({"nodeid": report.nodeid, "phase": report.when, "outcome": report.outcome,
            "longrepr": str(report.longrepr) if report.failed else None})
